namespace AIEngineerStudio.Models;

public sealed record AiModelInfo(
    string Id,
    string Provider,
    string Category,
    string Description,
    string BestFor,
    string PriceCoefficient)
{
    // Рекомендательные назначения на основе описаний каталога, не бенчмарки.
    public IReadOnlyList<string> Purposes
    {
        get
        {
            List<string> result = new();
            string text = $"{Description} {BestFor}".ToLowerInvariant();
            if (Category == "Универсальные") result.Add("Универсальные задачи");
            if (new[] { "код", "разработ", "программ", "рефактор", "wpf", "инженер", "архитект", "ревью", "code" }.Any(text.Contains)) result.Add("Программирование");
            if (Category == "Флагманские" || new[] { "анализ", "аналит", "рассужден", "логик", "исследован", "алгоритм", "reasoning" }.Any(text.Contains)) result.Add("Анализ и рассуждения");
            if (new[] { "текст", "документ", "контент", "переписк", "резюме", "спецификац" }.Any(text.Contains)) result.Add("Тексты и документы");
            if (Category == "Быстрые и экономичные") result.Add("Быстрые ответы");
            if (result.Count == 0) result.Add("Универсальные задачи");
            return result;
        }
    }

    public override string ToString() => Id;
}

